// smoke.spec.js — tool-specific checks for Mute Video and Remove Audio.
// Fixtures (generated by tests/make-video-fixtures.cjs with the vendored ffmpeg core, fully fictional):
//   sample-video.mp4 (H.264 + AAC: moving square + beeping tone), sample-video-silent.mp4 (no audio),
//   sample-video.webm (VP8 + Opus). Playwright's Chromium has no H.264/AAC decoder, so playback is checked on the WebM.
const { test, expect } = require('@playwright/test');
const fs = require('fs');
const path = require('path');

const fixture = (name) => path.join(__dirname, 'fixtures', name);

// Simulates a real drag-and-drop of a fixture onto the drop zone (optionally under another file name).
async function dropFiles(page, files) {
  const payload = files.map(({ file, name, type }) => ({ name: name || file, type: type || 'video/mp4', b64: fs.readFileSync(fixture(file)).toString('base64') }));
  await page.evaluate((items) => {
    const dt = new DataTransfer();
    for (const it of items) {
      const bin = Uint8Array.from(atob(it.b64), (c) => c.charCodeAt(0));
      dt.items.add(new File([bin], it.name, { type: it.type }));
    }
    const zone = document.getElementById('dropzone');
    zone.dispatchEvent(new DragEvent('dragenter', { bubbles: true, cancelable: true, dataTransfer: dt }));
    zone.dispatchEvent(new DragEvent('drop', { bubbles: true, cancelable: true, dataTransfer: dt }));
  }, payload);
}

async function loadAndMute(page, file, name) {
  await dropFiles(page, [{ file, name, type: file.endsWith('.webm') ? 'video/webm' : 'video/mp4' }]);
  await expect(page.locator('#info-audio')).toHaveText(/Yes/, { timeout: 30_000 });
  await page.click('#mute-btn');
  await expect(page.locator('#download')).toBeVisible({ timeout: 30_000 });
}

// Plays a <video> muted for a moment and reports how far it got and how many audio bytes Chromium decoded.
async function playAndMeasure(page, selector) {
  return page.evaluate(async (sel) => {
    const v = document.querySelector(sel);
    v.muted = true;
    await v.play();
    await new Promise((r) => setTimeout(r, 1500));
    v.pause();
    return { time: v.currentTime, audioBytes: v.webkitAudioDecodedByteCount, videoBytes: v.webkitVideoDecodedByteCount };
  }, selector);
}

test.describe('Mute Video and Remove Audio', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('./');
  });

  test('dropping sample-video.mp4 and pressing Remove audio downloads a new .mp4 without audio', async ({ page }) => {
    await dropFiles(page, [{ file: 'sample-video.mp4' }]);
    await expect(page.locator('#info-name')).toHaveText('sample-video.mp4');
    await expect(page.locator('#info-duration')).toHaveText(/0:06\.0/, { timeout: 30_000 });
    await expect(page.locator('#info-resolution')).toContainText('480 × 270');
    await expect(page.locator('#info-audio')).toHaveText(/Yes, 1 track/);
    await page.click('#mute-btn');
    const dl = page.locator('#download');
    await expect(dl).toHaveText('Download sample-video-muted.mp4', { timeout: 30_000 });

    const [download] = await Promise.all([page.waitForEvent('download'), dl.click()]);
    expect(download.suggestedFilename()).toBe('sample-video-muted.mp4');
    const out = fs.readFileSync(await download.path());
    const original = fs.readFileSync(fixture('sample-video.mp4'));
    expect(out.subarray(4, 8).toString('latin1')).toBe('ftyp'); // a real MP4 container
    expect(out.length).toBeGreaterThan(100_000);
    expect(out.length).toBeLessThan(original.length);
    expect(original.includes('mp4a')).toBe(true); // the input has an AAC track...
    expect(out.includes('mp4a')).toBe(false); // ...the output has none
    expect(out.includes('avc1')).toBe(true); // and the H.264 video is still there
    // This browser cannot decode H.264: the preview falls back to a note, which must not block the download.
    const canPlay = await page.evaluate(() => document.createElement('video').canPlayType('video/mp4; codecs="avc1.64001e"'));
    if (!canPlay) await expect(page.locator('#source-fallback')).toBeVisible();
  });

  test('the output plays in the page preview and reports no audio track', async ({ page }) => {
    await loadAndMute(page, 'sample-video.webm');
    const [download] = await Promise.all([page.waitForEvent('download'), page.click('#download')]);
    expect(download.suggestedFilename()).toBe('sample-video-muted.webm'); // same extension as the input
    await expect(page.locator('#result-audio')).toHaveText('No audio track (verified)');
    const src = await playAndMeasure(page, '#source-video');
    const out = await playAndMeasure(page, '#result-video');
    expect(out.time).toBeGreaterThan(0.3); // it really plays
    expect(out.videoBytes).toBeGreaterThan(0);
    expect(src.audioBytes).toBeGreaterThan(0); // the original decodes sound...
    expect(out.audioBytes).toBe(0); // ...the muted copy has nothing to decode
  });

  test('the result shows original and output size, nearly equal because the video is copied', async ({ page }) => {
    await loadAndMute(page, 'sample-video.mp4');
    const card = page.locator('#results .mv-result');
    await expect(card.locator('#result-original-size')).toHaveText(/\d+(\.\d)? KB/);
    await expect(card.locator('#result-output-size')).toHaveText(/\d+(\.\d)? KB/);
    const original = Number(await card.getAttribute('data-original-bytes'));
    const output = Number(await card.getAttribute('data-output-bytes'));
    expect(original).toBe(fs.statSync(fixture('sample-video.mp4')).size);
    const ratio = output / original;
    expect(ratio).toBeGreaterThan(0.85);
    expect(ratio).toBeLessThan(1);
    await expect(card.locator('#result-ratio')).toContainText(`${(Math.floor(ratio * 1000) / 10).toFixed(1)}%`);
  });

  test('a video that already has no audio shows an informational note', async ({ page }) => {
    await page.setInputFiles('#file-input', fixture('sample-video-silent.mp4'));
    await expect(page.locator('#info-audio')).toHaveText('No audio track', { timeout: 30_000 });
    const note = page.locator('#results .alert--info');
    await expect(note).toBeVisible();
    await expect(note).toContainText('no audio track');
    await expect(page.locator('#results .alert--error')).toHaveCount(0);
  });

  test('a non-video file shows an error, also when mixed with a valid video', async ({ page }) => {
    await page.setInputFiles('#file-input', fixture('sample.png'));
    const err = page.locator('#results .alert--error');
    await expect(err).toBeVisible();
    await expect(err).toContainText('sample.png');
    await expect(err).toContainText('not a supported video');
    await expect(page.locator('#source')).toBeHidden();

    // A file with a video extension that is not really a video is caught by ffmpeg.
    await dropFiles(page, [{ file: 'sample.txt', name: 'fake-clip.mp4' }]);
    await expect(page.locator('#results .alert--error')).toContainText('not a video this tool can read', { timeout: 30_000 });

    await dropFiles(page, [{ file: 'sample.pdf', name: 'notes.pdf', type: 'application/pdf' }, { file: 'sample-video.mp4' }]);
    await expect(page.locator('#results .alert--error')).toContainText('notes.pdf');
    await expect(page.locator('#info-audio')).toHaveText(/Yes/, { timeout: 30_000 });
    await expect(page.locator('#mute-btn')).toBeEnabled();
  });

  test('keyboard: Enter starts, Space plays the preview; Unicode names are preserved', async ({ page }) => {
    await dropFiles(page, [{ file: 'sample-video.webm', name: 'café clip ünïcode.webm', type: 'video/webm' }]);
    await expect(page.locator('#mute-btn')).toBeEnabled({ timeout: 30_000 });
    await page.evaluate(() => { document.activeElement && document.activeElement.blur(); document.getElementById('source-video').muted = true; });
    await page.keyboard.press('Space');
    await expect.poll(() => page.evaluate(() => !document.getElementById('source-video').paused)).toBe(true);
    await page.keyboard.press('Space');
    await page.keyboard.press('Enter');
    const dl = page.locator('#download');
    await expect(dl).toHaveText('Download café clip ünïcode-muted.webm', { timeout: 30_000 });
    const [download] = await Promise.all([page.waitForEvent('download'), dl.click()]);
    expect(download.suggestedFilename()).toBe('café clip ünïcode-muted.webm');
  });

  test('works at 390px wide', async ({ page }) => {
    await page.setViewportSize({ width: 390, height: 844 });
    await page.goto('./');
    const zone = await page.locator('#dropzone').boundingBox();
    expect(zone.y).toBeLessThan(844); // drop zone above the fold
    await loadAndMute(page, 'sample-video.webm', 'a-rather-long-holiday-clip-name-for-phones.webm');
    const widths = await page.evaluate(() => ({ doc: document.documentElement.scrollWidth, win: window.innerWidth }));
    expect(widths.doc).toBeLessThanOrEqual(widths.win + 1);
    for (const sel of ['#download', '#result-video', '#mute-btn', '#source-video']) {
      await expect(page.locator(sel)).toBeVisible();
      const box = await page.locator(sel).boundingBox();
      expect(box.x).toBeGreaterThanOrEqual(0);
      expect(box.x + box.width, `${sel} overflows`).toBeLessThanOrEqual(391);
    }
    const [download] = await Promise.all([page.waitForEvent('download'), page.click('#download')]);
    expect(download.suggestedFilename()).toBe('a-rather-long-holiday-clip-name-for-phones-muted.webm');
  });

  test('__demo shows a finished result with the bundled Sample Video', async ({ page }) => {
    await page.evaluate(() => window.__demo());
    await expect(page.locator('#download')).toHaveText('Download sample-video-muted.webm');
    await expect(page.locator('#results .alert--error')).toHaveCount(0);
    await expect(page.locator('#result-video')).toBeVisible();
  });
});
